"1733 :     private ArrayRealVector findEigenvector(final double eigenvalue,
1734 :                                            final double[] d, final double[] l) {
1735 : 
1736 :         // compute the LDLt and UDUt decompositions of the
1737 :         // perfectly shifted tridiagonal matrix
1738 :         final int m = main.length;
1739 :         stationaryQuotientDifferenceWithShift(d, l, eigenvalue);
1740 :         progressiveQuotientDifferenceWithShift(d, l, eigenvalue);
1741 : 
1742 :         // select the twist index leading to
1743 :         // the least diagonal element in the twisted factorization
1744 :         int r = m - 1;
1745 :         double minG = Math.abs(work[6 * r] + work[6 * r + 3] + eigenvalue);
1746 :         int sixI = 0;
1747 :         for (int i = 0; i < m - 1; ++i) {
1748 :             final double absG = Math.abs(work[sixI] + d[i] * work[sixI + 9] / work[sixI + 10]);
1749 :             if (absG < minG) {
1750 :                 r = i;
1751 :                 minG = absG;
1752 :             }
1753 :             sixI += 6;
1754 :         }
1755 : 
1756 :         // solve the singular system by ignoring the equation
1757 :         // at twist index and propagating upwards and downwards
1758 :         double[] eigenvector = new double[m];
1759 :         double n2 = 1;
1760 :         eigenvector[r] = 1;
1761 :         double z = 1;
1762 :         for (int i = r - 1; i >= 0; --i) {
1763 :             z *= -work[6 * i + 2];
1764 :             eigenvector[i] = z;
1765 :             n2 += z * z;
1766 :         }
1767 :         z = 1;
1768 :         for (int i = r + 1; i < m; ++i) {
1769 :             z *= -work[6 * i - 1];
1770 :             eigenvector[i] = z;
1771 :             n2 += z * z;
1772 :         }
1773 : 
1774 :         // normalize vector
1775 :         final double inv = 1.0 / Math.sqrt(n2);
1776 :         for (int i = 0; i < m; ++i) {
1777 :             eigenvector[i] *= inv;
1778 :         }
1779 : 
1780 :         return (transformer == null) ?
1781 :                new ArrayRealVector(eigenvector, false) :
1782 :                new ArrayRealVector(transformer.getQ().operate(eigenvector), false);
1783 : 
1784 :     }"

